assert len(M) == 20, len(M)
for name, (cat, instr, arch) in M.items():
    obj = {"name": name, "category": cat, "instruction": instr,
           "architecture_thought": arch}
    fp = os.path.join(OUT, "r23_%s.json" % name)
    with open(fp, "w", encoding="utf-8", newline="\n") as fh:
        json.dump(obj, fh, ensure_ascii=False, indent=2)
print("meta written:", len(M))
